config.script:
// Build the identity pieces the form needs. Like solar2, we GENERATE the
// email local part ourselves (human-looking: first+last+random digits) rather
// than asking for an address - a generator mints its own usernames. Names and
// password come from the SDK identity; domain rotates over solar2's regional
// table unless hotmailDomain is set. identity.* / addresses.0.* come from the
// scrolls SDK runtime.
function rnd(n){ return Math.floor(Math.random() * n); }
// solar2 GetRandomUsername: mint a human-looking local part. We do NOT inject
// the identity name into this script - a name with a quote/apostrophe would
// break the JS at parse time (raw {{}} substitution). Build from letter
// syllables instead; names are filled separately via safe fill-node values.
var syl = ["an","bel","cor","dan","el","fen","gar","han","iv","jo","ka","li","mar","nor","os","per","qu","ri","sam","tan","ur","vi","wil","ya","zo"];
function word(){ return syl[rnd(syl.length)] + syl[rnd(syl.length)] + (Math.random()<0.5 ? syl[rnd(syl.length)] : ""); }
var w1 = word(), w2 = word();
var digits = String(rnd(900) + 100);
var shapes = [
  w1 + w2 + digits,
  w1 + "." + w2 + digits,
  w1 + w2.charAt(0) + digits,
  w1.charAt(0) + w2 + digits,
  w1 + digits + w2
];
var local = shapes[rnd(shapes.length)];
// The live surface only offers a short domain list (e.g. @outlook.com,
// @outlook.in, @hotmail.com) - solar2's 12-region table is from an older
// surface and must NOT be pre-baked. We just express a preference: hotmail
// toggle -> prefer @hotmail.com, else prefer @outlook.com. The domain step
// picks from what's actually offered and falls back, never fails.
var hotmail = String("{{inputs.hotmailDomain}}").toLowerCase() === "true";
var wantDom = hotmail ? "hotmail.com" : "outlook.com";
// dob/country are engine-formatted (digits, ISO code) - safe to inline. Strip
// anything that could break the literal anyway.
var dob = ("{{identity.dob}}" || "").replace(/[^0-9\-\/.]/g, "");
var y = "", m = "", d = "";
var mm = dob.match(/(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})/);
if (mm) { y = mm[1]; m = String(parseInt(mm[2], 10)); d = String(parseInt(mm[3], 10)); }
else { var m2 = dob.match(/(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{4})/); if (m2) { d = String(parseInt(m2[1], 10)); m = String(parseInt(m2[2], 10)); y = m2[3]; } }
if (!y) { y = "1994"; m = "6"; d = "15"; }
var months = ["January","February","March","April","May","June","July","August","September","October","November","December"];
var mNum = Math.min(12, Math.max(1, parseInt(m, 10)));
var monthName = months[mNum - 1];
var year = parseInt(y, 10); if (year > 2007) year = 1994;
return {
  emailLocal: local,
  wantDomain: wantDom,
  month: monthName,
  monthNum: String(mNum),
  day: String(parseInt(d, 10) || 15),
  year: String(year)
};

// Load gate for the fluent=2 signup surface. The mail app redirects to
// signup.live.com/signup?...&fluent=2 and renders 'Create your Microsoft
// account'. Wait for the email box or the heading, detect a block/redirect.
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
var tries = Number("{{gateTries}}") || 0;
var deadline = Date.now() + 45000;
while (Date.now() < deadline) {
  var t = (document.title || "").toLowerCase();
  if (t.indexOf("blocked") !== -1) throw new Error("Account creation blocked at load - exit IP is flagged");
  if (document.querySelector("input[name='email']")) return { state: "ready", tries: 0 };
  if (t.indexOf("create your microsoft account") !== -1 || t.indexOf("account") !== -1) {
    if (document.querySelector("input[name='email'], input[type='email']")) return { state: "ready", tries: 0 };
  }
  var body = (document.body && (document.body.innerText || ""));
  if (/unusual activity|temporarily blocked|try again later|verify your identity/i.test(body)) throw new Error("Microsoft served a block page - rotate the exit IP");
  await sleep(500);
}
if (tries >= 1) {
  var ti = (document.title || "").slice(0, 80); var u = ""; try { u = location.href.slice(0, 80); } catch (e) {}
  throw new Error("create_account page never rendered the email box. title='" + ti + "' url=" + u);
}
return { state: "reload", tries: tries + 1 };

// Wrap fetch/XHR early and stash the Arkose data[blob] off the POST body.
if (!window.__scBlobHooked) {
  window.__scBlobHooked = true; window.__arkoseBlob = "";
  var pick = function (body) { if (!body) return ""; try { var s = typeof body === "string" ? body : ""; var m = s.match(/data%5Bblob%5D=([^&]+)/) || s.match(/data\[blob\]=([^&]+)/); return m ? decodeURIComponent(m[1]) : ""; } catch (e) { return ""; } };
  var of = window.fetch;
  window.fetch = function (url, opts) { try { if (String(url).indexOf("client-api.arkoselabs.com/fc/gt2/public_key/") !== -1) { var b = pick(opts && opts.body); if (b) window.__arkoseBlob = b; } } catch (e) {} return of.apply(this, arguments); };
  var oo = XMLHttpRequest.prototype.open, os = XMLHttpRequest.prototype.send;
  XMLHttpRequest.prototype.open = function (m, u) { this.__scUrl = u; return oo.apply(this, arguments); };
  XMLHttpRequest.prototype.send = function (body) { try { if (String(this.__scUrl).indexOf("client-api.arkoselabs.com/fc/gt2/public_key/") !== -1) { var b = pick(body); if (b) window.__arkoseBlob = b; } } catch (e) {} return os.apply(this, arguments); };
}
return "armed";

// Domain is a Fluent dropdown (button#domainDropdownId) whose options are
// .fui-Option / [role=option] with text like '@outlook.com'. The live surface
// offers only a short list (e.g. @outlook.com, @outlook.in, @hotmail.com), so
// we pick from what is ACTUALLY offered: prefer the wanted domain, else fall
// back to the first offered option. Never fails on domain. Returns the picked
// domain (no @) so the full address is built from reality.
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
var want = ("@" + (("{{wantDomain}}" || "outlook.com").trim().toLowerCase()));
var btn = document.querySelector("button#domainDropdownId");
if (!btn) return ("outlook.com");
var cur = (btn.innerText || "").trim().toLowerCase();
if (cur.indexOf("@") === 0 && cur === want) return cur.slice(1);
btn.click();
var deadline = Date.now() + 9000; var offered = []; var pickEl = null;
while (Date.now() < deadline) {
  var opts = document.querySelectorAll("[role='option'], .fui-Option");
  offered = []; pickEl = null;
  for (var i = 0; i < opts.length; i++) {
    var tx = (opts[i].innerText || "").trim().toLowerCase();
    if (!tx || tx.indexOf("@") !== 0) continue;
    offered.push(tx);
    if (tx === want) pickEl = opts[i];
  }
  if (offered.length) break;
  await sleep(250);
}
if (!offered.length) { try { document.body.click(); } catch (e) {} return cur.indexOf("@") === 0 ? cur.slice(1) : "outlook.com"; }
var chosenTx = pickEl ? want : offered[0];
if (!pickEl) {
  var all = document.querySelectorAll("[role='option'], .fui-Option");
  for (var k = 0; k < all.length; k++) { var t2 = (all[k].innerText || "").trim().toLowerCase(); if (t2 === chosenTx) { pickEl = all[k]; break; } }
}
if (pickEl) pickEl.click();
return chosenTx.slice(1);

// After Next on the email step: scan for a taken/invalid error, else confirm
// we reached the password box.
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
function vis(el){if(!el)return false;var r=el.getBoundingClientRect();var s=getComputedStyle(el);return r.width>1&&r.height>1&&s.visibility!=='hidden'&&s.display!=='none';}
// Reaching the password box = the email was ACCEPTED. Check that FIRST so a
// transient/lingering alert can never be misread as 'taken'. Only treat an
// alert as a real rejection when its text matches a taken/invalid pattern.
function takenTxt(s){ return /already have an account|already exists|someone already|already taken|is taken|try another|pick a different|not available|can't use|cannot use|invalid/i.test(s||""); }
for (var pass = 0; pass < 5; pass++) {
  if (vis(document.querySelector("input[type='password']"))) return "ok";
  var err = document.querySelector("[role='alert'], .fui-Text[class*='error'], [id*='Error'], [id*='error']");
  var et = err ? (err.innerText || "").trim() : "";
  if (vis(err) && et && takenTxt(et)) return "taken:" + et.slice(0, 160);
  var body = (document.body && document.body.innerText || "");
  if (/account creation has been blocked/i.test((document.title||"") + " " + body)) throw new Error("Account creation blocked after email step");
  await sleep(1200);
  // re-check password each pass; only a persistent taken-pattern alert counts
  if (vis(document.querySelector("input[type='password']"))) return "ok";
  if (vis(err) && et && takenTxt(et)) return "taken:" + et.slice(0, 160);
  if (takenTxt(body)) return "taken:" + body.replace(/\s+/g, " ").slice(0, 140);
}
return vis(document.querySelector("input[type='password']")) ? "ok" : "unknown";

// The minted username collided. Like solar2, regenerate instead of failing:
// build a fresh higher-entropy local part from first/last + more digits,
// clear and refill the email box, click Next, and hand the new local back so
// fullEmail/emailLocal can be updated before the taken-check runs again.
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
function setVal(el,val){el.focus();el.value="";el.dispatchEvent(new Event("input",{bubbles:true}));el.value=val;el.dispatchEvent(new Event("input",{bubbles:true}));el.dispatchEvent(new Event("change",{bubbles:true}));el.dispatchEvent(new Event("blur",{bubbles:true}));}
window.__scRegenN = (window.__scRegenN || 0) + 1;
if (window.__scRegenN > 4) throw new Error("Username keeps colliding after 4 regenerations - pick a different profile or run again");
function rnd(n){ return Math.floor(Math.random() * n); }
// No identity name injection (parse-safe); mint a fresh higher-entropy local
// part from syllables + 6 digits.
var syl = ["an","bel","cor","dan","el","fen","gar","han","iv","jo","ka","li","mar","nor","os","per","qu","ri","sam","tan","ur","vi","wil","ya","zo"];
function word(){ return syl[rnd(syl.length)] + syl[rnd(syl.length)] + (Math.random()<0.5 ? syl[rnd(syl.length)] : ""); }
var w1 = word(), w2 = word();
var digits = String(rnd(900000) + 100000);
var shapes = [
  w1 + w2 + digits,
  w1 + "." + w2 + digits,
  w1.charAt(0) + w2 + digits,
  w1 + w2.charAt(0) + digits,
  w2 + w1 + digits
];
var local = shapes[rnd(shapes.length)];
// If the email box is gone we already ADVANCED (password page) - the prior
// 'taken' was a stale/lingering alert. Don't refill or click; hand back the
// current local so the taken-check re-runs and sees the password box -> ok.
var em = document.querySelector("input[name='email']");
if (!em || document.querySelector("input[type='password']")) return "{{emailLocal}}";
setVal(em, local);
await sleep(400 + Math.random() * 500);
var next = document.querySelector("button[data-testid='primaryButton']:not([disabled]), button[type='submit']:not([disabled])");
if (next) next.click();
// give the availability check a moment so the old alert is gone before the
// taken-check reads the page again
await sleep(3000);
return local;

// Click the password page's primary Next, tolerating a
// disabled->enabled transition and re-renders. Polls for any visible,
// enabled submit control (testid primaryButton, type=submit, or a
// button labelled Next/Continue/etc).
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
function vis(el){if(!el)return false;var r=el.getBoundingClientRect();var s=getComputedStyle(el);return r.width>1&&r.height>1&&s.visibility!=='hidden'&&s.display!=='none';}
function findNext(){
  var cands = document.querySelectorAll("button[data-testid='primaryButton'], button[type='submit'], input[type='submit'], button");
  for (var i=0;i<cands.length;i++){var b=cands[i];if(!vis(b))continue;var dis=b.disabled||b.getAttribute('aria-disabled')==='true';var t=((b.innerText||b.value||'')+'').trim();var tid=b.getAttribute('data-testid')||'';if(dis)continue;if(tid==='primaryButton'||b.type==='submit'||/^(next|continue|submit|sign up|create account)$/i.test(t))return b;}
  return null;
}
var deadline = Date.now() + 60000;
while (Date.now() < deadline) {
  if (/account creation has been blocked/i.test((document.title||'')+' '+(document.body&&document.body.innerText||''))) throw new Error('Account creation blocked at password step');
  var b = findNext();
  if (b) { try { b.scrollIntoView({block:'center'}); } catch(e){} await sleep(200); b.click(); return 'clicked'; }
  await sleep(400);
}
throw new Error('password Next button never became clickable');

// Country + birthdate page (fluent=2). Country/Birth month/Birth day are
// Fluent dropdown buttons; Birth year is a number input. Click a dropdown,
// then click the matching [role=option]. Empty country leaves the geo default.
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
function vis(el){if(!el)return false;var r=el.getBoundingClientRect();var s=getComputedStyle(el);return r.width>1&&r.height>1&&s.visibility!=='hidden'&&s.display!=='none';}
// Fluent v9 comboboxes (role=combobox, aria-expanded, a portaled listbox).
// Clicking the portaled [role=option] node is unreliable - it mounts in a
// body-level layer and the click can miss. The locale- and markup-proof way
// is KEYBOARD, exactly how a human uses it: focus the button, open with
// Enter/ArrowDown, ArrowDown to the index, Enter to commit. Verify via the
// button's value/aria-invalid clearing; fall back to clicking the option.
function key(el, type, k){ el.dispatchEvent(new KeyboardEvent(type, { key: k, code: k, bubbles: true, cancelable: true })); }
function press(el, k){ key(el,'keydown',k); key(el,'keyup',k); }
function getVal(btn){ var s = btn.querySelector("[data-testid='truncatedSelectedText']"); var t = ((s && s.innerText) || btn.innerText || "").trim(); var v = btn.getAttribute("value") || ""; return (v || t); }
async function openCombo(btn){
  btn.focus(); await sleep(150);
  btn.click(); await sleep(300);
  if (btn.getAttribute("aria-expanded") !== "true") { press(btn, "Enter"); await sleep(300); }
  if (btn.getAttribute("aria-expanded") !== "true") { press(btn, "ArrowDown"); await sleep(300); }
  var deadline = Date.now() + 8000;
  while (Date.now() < deadline) {
    var lb = document.querySelector("[role='listbox']");
    if (lb) return lb;
    if (btn.getAttribute("aria-expanded") === "true") return document.querySelector("[role='listbox']") || btn;
    await sleep(200);
  }
  return null;
}
async function pickByIndex(btnSel, idx1, isSet){
  var btn = document.querySelector(btnSel); if (!btn) return "no-btn:" + btnSel;
  for (var attempt = 0; attempt < 2; attempt++) {
    var before = getVal(btn);
    var lb = await openCombo(btn);
    if (lb) {
      // keyboard: ArrowDown idx1 times from the top, then Enter
      var i; for (i = 0; i < idx1; i++) { press(btn, "ArrowDown"); await sleep(90); }
      press(btn, "Enter"); await sleep(300);
      if (getVal(btn) !== before && getVal(btn) !== "") return "kbd:" + getVal(btn);
      // fallback: click the nth option in the open listbox (portal-safe query)
      var opts = document.querySelectorAll("[role='listbox'] [role='option'], [role='option'], .fui-Option");
      if (opts.length) {
        var j = Math.max(1, Math.min(opts.length, idx1)) - 1;
        try { opts[j].scrollIntoView({block:'nearest'}); } catch(e){}
        opts[j].click(); await sleep(300);
        if (getVal(btn) !== before && getVal(btn) !== "") return "click:" + getVal(btn);
      }
      // close any open list before retrying
      press(btn, "Escape"); try { document.body.click(); } catch(e){} await sleep(300);
    }
  }
  return "failed:" + btnSel;
}
var parts = "{{dob}}".split("|");
// parts: [monthName, monthNum, day, year]
var monthNum = parseInt(parts[1], 10) || 6;
var dayNum = parseInt(parts[2], 10) || 15;
var results = {};
// Country is AUTO-SET from the exit IP's geo (e.g. value=ES) and must NOT be
// overridden - a proxy/country mismatch is a flag. We leave it alone. Only
// month/day/year are ours to fill. Wait for the birthdate page to settle
// first - the fields mount progressively after the password Next.
var readyDeadline = Date.now() + 30000;
while (Date.now() < readyDeadline) {
  if (/account creation has been blocked/i.test((document.title||"")+" "+(document.body&&document.body.innerText||""))) throw new Error("Account creation blocked at birthdate step");
  if (document.querySelector("button#BirthMonthDropdown") || document.querySelector("input[name='BirthYear']")) break;
  await sleep(400);
}
results.month = await pickByIndex("button#BirthMonthDropdown", monthNum);
await sleep(400 + Math.random() * 600);
results.day = await pickByIndex("button#BirthDayDropdown", dayNum);
await sleep(300 + Math.random() * 400);
var y = document.querySelector("input[name='BirthYear']");
if (y) { y.focus(); y.value = ""; y.dispatchEvent(new Event("input", { bubbles: true })); y.value = parts[3]; y.dispatchEvent(new Event("input", { bubbles: true })); y.dispatchEvent(new Event("change", { bubbles: true })); y.dispatchEvent(new Event("blur", { bubbles: true })); }
// only month/day are mandatory here; surface a failure on either loudly
var bad = []; ["month", "day"].forEach(function (k) { var v = String(results[k] || ""); if (v.indexOf("failed") === 0 || v.indexOf("no-btn") === 0 || v.indexOf("no-list") === 0) bad.push(k + "=" + v); });
if (bad.length) throw new Error("birthdate fields not set: " + bad.join(", "));
return "done:" + JSON.stringify(results);

// Click the birthdate page's primary Next, tolerating a
// disabled->enabled transition and re-renders. Polls for any visible,
// enabled submit control (testid primaryButton, type=submit, or a
// button labelled Next/Continue/etc).
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
function vis(el){if(!el)return false;var r=el.getBoundingClientRect();var s=getComputedStyle(el);return r.width>1&&r.height>1&&s.visibility!=='hidden'&&s.display!=='none';}
function findNext(){
  var cands = document.querySelectorAll("button[data-testid='primaryButton'], button[type='submit'], input[type='submit'], button");
  for (var i=0;i<cands.length;i++){var b=cands[i];if(!vis(b))continue;var dis=b.disabled||b.getAttribute('aria-disabled')==='true';var t=((b.innerText||b.value||'')+'').trim();var tid=b.getAttribute('data-testid')||'';if(dis)continue;if(tid==='primaryButton'||b.type==='submit'||/^(next|continue|submit|sign up|create account)$/i.test(t))return b;}
  return null;
}
var deadline = Date.now() + 60000;
while (Date.now() < deadline) {
  if (/account creation has been blocked/i.test((document.title||'')+' '+(document.body&&document.body.innerText||''))) throw new Error('Account creation blocked at birthdate step');
  var b = findNext();
  if (b) { try { b.scrollIntoView({block:'center'}); } catch(e){} await sleep(200); b.click(); return 'clicked'; }
  await sleep(400);
}
throw new Error('birthdate Next button never became clickable');

// Names page. The field IDs (firstNameInput/lastNameInput) are NOT stable
// across locales - a non-English exit can render different ids, so resolve
// the two name inputs locale-agnostically and hand exact selectors back.
// Priority: known ids -> autocomplete given/family-name -> name/aria hints ->
// the only two visible text inputs on the page (first = first name).
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
function vis(el){if(!el)return false;var r=el.getBoundingClientRect();var s=getComputedStyle(el);return r.width>1&&r.height>1&&s.visibility!=='hidden'&&s.display!=='none'&&el.offsetParent!==null;}
function uniq(el, base){ if(!el) return ""; if(el.id) return "#" + el.id; var nm=el.getAttribute("name"); if(nm) return "input[name='" + nm + "']"; return base; }
function findNames(){
  var f = document.querySelector("input#firstNameInput, input[autocomplete='given-name'], input[name*='first' i], input[id*='first' i]");
  var l = document.querySelector("input#lastNameInput, input[autocomplete='family-name'], input[name*='last' i], input[id*='last' i]");
  if (vis(f) && vis(l)) return { f: f, l: l };
  // fallback: the two visible text inputs (exclude email/password/hidden)
  var all = document.querySelectorAll("input[type='text'], input:not([type])");
  var vis2 = [];
  for (var i=0;i<all.length;i++){var e=all[i];if(!vis(e))continue;var t=(e.type||'').toLowerCase();if(t==='email'||t==='password'||t==='hidden'||t==='checkbox')continue;vis2.push(e);}
  if (vis2.length >= 2) return { f: vis2[0], l: vis2[1] };
  return null;
}
var deadline = Date.now() + 45000;
while (Date.now() < deadline) {
  var body = (document.body && document.body.innerText || "");
  if (/account creation has been blocked/i.test((document.title||"") + " " + body)) throw new Error("Account creation blocked before names step");
  var r = findNames();
  if (r) {
    return { first: uniq(r.f, "input[autocomplete='given-name']"), last: uniq(r.l, "input[autocomplete='family-name']") };
  }
  await sleep(500);
}
throw new Error("name fields never appeared after country/DOB");

// Click the names page's primary Next, tolerating a
// disabled->enabled transition and re-renders. Polls for any visible,
// enabled submit control (testid primaryButton, type=submit, or a
// button labelled Next/Continue/etc).
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
function vis(el){if(!el)return false;var r=el.getBoundingClientRect();var s=getComputedStyle(el);return r.width>1&&r.height>1&&s.visibility!=='hidden'&&s.display!=='none';}
function findNext(){
  var cands = document.querySelectorAll("button[data-testid='primaryButton'], button[type='submit'], input[type='submit'], button");
  for (var i=0;i<cands.length;i++){var b=cands[i];if(!vis(b))continue;var dis=b.disabled||b.getAttribute('aria-disabled')==='true';var t=((b.innerText||b.value||'')+'').trim();var tid=b.getAttribute('data-testid')||'';if(dis)continue;if(tid==='primaryButton'||b.type==='submit'||/^(next|continue|submit|sign up|create account)$/i.test(t))return b;}
  return null;
}
var deadline = Date.now() + 60000;
while (Date.now() < deadline) {
  if (/account creation has been blocked/i.test((document.title||'')+' '+(document.body&&document.body.innerText||''))) throw new Error('Account creation blocked at names step');
  var b = findNext();
  if (b) { try { b.scrollIntoView({block:'center'}); } catch(e){} await sleep(200); b.click(); return 'clicked'; }
  await sleep(400);
}
throw new Error('names Next button never became clickable');

// After names: detect a block, an SMS/identity gate, the captcha frame, or a
// straight-through landing.
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
function vis(el){if(!el)return false;var r=el.getBoundingClientRect();var s=getComputedStyle(el);return r.width>1&&r.height>1&&s.visibility!=='hidden'&&s.display!=='none';}
var deadline = Date.now() + 30000;
while (Date.now() < deadline) {
  var body = (document.body && document.body.innerText || "");
  if (/account creation has been blocked/i.test((document.title||"") + " " + body)) throw new Error("Account creation blocked after names step");
  if (/When you need to prove|verify your phone|enter.*phone number|text you a code/i.test(body)) return "sms-gate";
  if (location.href.indexOf("account.microsoft.com") !== -1 || location.href.indexOf("outlook.live.com/mail") !== -1) return "landed";
  if (vis(document.querySelector("#enforcementFrame"))) return "captcha";
  if (document.querySelector("iframe[src*='arkoselabs'], iframe[src*='funcaptcha']")) return "captcha";
  await sleep(500);
}
return "timeout";

// Read the stashed Arkose data[blob]; give the challenge a moment to POST.
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
var deadline = Date.now() + 20000;
while (Date.now() < deadline) { if (window.__arkoseBlob) return window.__arkoseBlob; await sleep(400); }
return "";

// Cross-frame token submit: inject a submitter into the cross-origin
// enforcementFrame, else postMessage the token up to the page listener.
var token = "{{captchaToken}}";
if (!token) return "skipped-no-challenge";
var enc = document.getElementById("enforcementFrame");
var posted = false;
try {
  var encWin = enc && (enc.contentWindow || enc);
  var encDoc = enc && (enc.contentDocument || (encWin && encWin.document));
  if (encDoc) {
    var s = encDoc.createElement("SCRIPT");
    s.textContent = "function CaptchaSubmit(token){ var j = JSON.stringify({ eventId:'challenge-complete', payload:{ sessionToken: token } }); parent.postMessage(j, '*'); }";
    encDoc.documentElement.appendChild(s);
    encWin.CaptchaSubmit(token);
    posted = true;
  }
} catch (e) {}
if (!posted) {
  var j = JSON.stringify({ eventId: "challenge-complete", payload: { sessionToken: token } });
  if (enc && enc.contentWindow) enc.contentWindow.postMessage(j, "*");
  window.postMessage(j, "*");
}
return posted ? "injected" : "posted";

// solar2 fills a backup/verify-email page after the captcha. It may or may
// not appear. If it does and a backupEmail variable is set, fill the address
// (and its confirm box) and click Next; empty backupEmail or no page = skip.
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
function vis(el){if(!el)return false;var r=el.getBoundingClientRect();var s=getComputedStyle(el);return r.width>1&&r.height>1&&s.visibility!=='hidden'&&s.display!=='none';}
function setVal(el,val){el.focus();el.value=val;el.dispatchEvent(new Event("input",{bubbles:true}));el.dispatchEvent(new Event("change",{bubbles:true}));el.dispatchEvent(new Event("blur",{bubbles:true}));}
// NOTE: no backupEmail text is injected into this script (raw {{}} into a
// JS string would break on quotes). The value is written by the fill node
// downstream; this script only DETECTS the backup-email page.
var deadline = Date.now() + 15000;
while (Date.now() < deadline) {
  if (/account creation has been blocked/i.test((document.title||"") + " " + (document.body && document.body.innerText || ""))) throw new Error("Account creation blocked at backup-email step");
  if (location.href.indexOf("account.microsoft.com") !== -1 || location.href.indexOf("outlook.live.com/mail") !== -1) return "no-page-landed";
  var em = document.querySelector("input[type='email'], input[name*='mail' i], input[id*='mail' i], input[aria-label*='email' i]");
  if (vis(em)) return "present";
  await sleep(600);
}
return "no-page";

// Click the backup-email page's primary Next, tolerating a
// disabled->enabled transition and re-renders. Polls for any visible,
// enabled submit control (testid primaryButton, type=submit, or a
// button labelled Next/Continue/etc).
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
function vis(el){if(!el)return false;var r=el.getBoundingClientRect();var s=getComputedStyle(el);return r.width>1&&r.height>1&&s.visibility!=='hidden'&&s.display!=='none';}
function findNext(){
  var cands = document.querySelectorAll("button[data-testid='primaryButton'], button[type='submit'], input[type='submit'], button");
  for (var i=0;i<cands.length;i++){var b=cands[i];if(!vis(b))continue;var dis=b.disabled||b.getAttribute('aria-disabled')==='true';var t=((b.innerText||b.value||'')+'').trim();var tid=b.getAttribute('data-testid')||'';if(dis)continue;if(tid==='primaryButton'||b.type==='submit'||/^(next|continue|submit|sign up|create account)$/i.test(t))return b;}
  return null;
}
var deadline = Date.now() + 60000;
while (Date.now() < deadline) {
  if (/account creation has been blocked/i.test((document.title||'')+' '+(document.body&&document.body.innerText||''))) throw new Error('Account creation blocked at backup-email step');
  var b = findNext();
  if (b) { try { b.scrollIntoView({block:'center'}); } catch(e){} await sleep(200); b.click(); return 'clicked'; }
  await sleep(400);
}
throw new Error('backup-email Next button never became clickable');

// Wait for the account to land (mail app or account.microsoft.com), re-posting
// the token in case the first submit raced the listener. Empty token means the
// challenge never appeared and Microsoft let us straight through.
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
var token = "{{captchaToken}}";
var j = token ? JSON.stringify({ eventId: "challenge-complete", payload: { sessionToken: token } }) : "";
var deadline = Date.now() + 120000;
while (Date.now() < deadline) {
  var u = "";
  try { u = location.href; } catch (e) {}
  if (u.indexOf("account.microsoft.com") !== -1 || u.indexOf("outlook.live.com/mail") !== -1) return "landed";
  var body = (document.body && document.body.innerText || "");
  if (/account creation has been blocked/i.test((document.title||"") + " " + body)) throw new Error("Account creation blocked after captcha");
  if (j) {
    var f = document.getElementById("enforcementFrame");
    if (f) { try { if (f.contentWindow) f.contentWindow.postMessage(j, "*"); window.postMessage(j, "*"); } catch (e) {} }
  }
  await sleep(3000);
}
throw new Error("Signup never completed - no redirect to the mailbox");

// Click through privacy / stay-signed-in / welcome prompts.
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
function vis(el){if(!el)return false;var r=el.getBoundingClientRect();var s=getComputedStyle(el);return r.width>1&&r.height>1&&s.visibility!=='hidden'&&s.display!=='none';}
var deadline = Date.now() + 20000;
while (Date.now() < deadline) {
  var hit = false;
  var btns = document.querySelectorAll("button, a[role='button'], input[type='submit']");
  for (var i = 0; i < btns.length; i++) {
    if (!vis(btns[i])) continue;
    var t = ((btns[i].innerText || btns[i].value || "")).trim();
    if (/^(accept|next|yes|ok|continue|get started|done|skip)$/i.test(t)) { btns[i].click(); hit = true; break; }
  }
  var stay = document.querySelector("#idBtn_Back, [name='DontShowAgain']");
  if (vis(stay)) { stay.click(); hit = true; }
  if (!hit) break;
  await sleep(1500);
}
return "done";
